declare const __CARD_VERSION__: string;

interface Window {
  customCards?: {
    type: string;
    name?: string;
    description?: string;
    preview?: boolean;
  }[];
}

/** Generated by translations-plugin.ts at build time. */
declare module "translations:loaders" {
  /** Languages with a file in src/translations/. */
  export const languages: string[];
  /** One dynamic import per "<language>/<section>/<part>" chunk. */
  export const loaders: Record<string, () => Promise<{ default: Record<string, string> }>>;
}
